  function duplicateRace(id){var source=races().find(function(r){return r.id===id});if(!source)return;var all=races(),base=source.name.replace(/\s+\d+$/,''),pattern=new RegExp('^'+base.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:\\s+(\\d+))?$','i'),highest=1;all.forEach(function(r){var match=r.name.match(pattern);if(match)highest=Math.max(highest,Number(match[1])||1)});var copy=JSON.parse(JSON.stringify(source));copy.id=String(Date.now());copy.name=base+' '+(highest+1);copy.status='STAGING';copy.currentIndex=0;copy.createdAt=new Date().toISOString();copy.results=[];copy.schedule.forEach(function(stage){stage.completed=false});all.push(copy);write(RACE_KEY,all);renderSetup();var select=q('#v2-current-race');if(select)select.value=copy.id}

